def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_my = my[-1]
    last_opp = opp[-1]

    if n == 99:
        return 'D'

    if n == 3:
        return 'D'
    if n == 7:
        return 'D'
    if n < 8:
        return 'C'

    if n < 12:
        if last_opp == 'D':
            if last_my == 'D':
                return 'C'
            else:
                return 'D'
        else:
            return 'C'

    window = min(10, n)
    start = n - window

    copy_matches = 0
    total_trans = 0
    for t in range(start, n):
        if t == 0:
            continue
        total_trans += 1
        if opp[t] == my[t-1]:
            copy_matches += 1
    copy_rate = copy_matches / total_trans if total_trans > 0 else 0

    if copy_rate > 0.7:
        return 'C'

    n_D_after_my_D = 0
    n_after_my_D = 0
    n_D_after_my_C = 0
    n_after_my_C = 0
    for t in range(start, n):
        if t == 0:
            continue
        prev_my = my[t-1]
        curr_opp = opp[t]
        if prev_my == 'D':
            n_after_my_D += 1
            if curr_opp == 'D':
                n_D_after_my_D += 1
        else:
            n_after_my_C += 1
            if curr_opp == 'D':
                n_D_after_my_C += 1

    p_D_given_my_D = n_D_after_my_D / n_after_my_D if n_after_my_D > 0 else 0.5
    p_D_given_my_C = n_D_after_my_C / n_after_my_C if n_after_my_C > 0 else 0.5

    if p_D_given_my_C > 0.25:
        return 'D'

    if p_D_given_my_D > p_D_given_my_C + 0.2 and n_after_my_D >= 1:
        if last_opp == 'D':
            if last_my == 'D':
                return 'C'
            else:
                return 'D'
        else:
            return 'C'

    return 'D'
